<?php
namespace App\Commands\AiOps;
use App\Commands\SafeBaseCommand; use App\Commands\Support\SubsCommandTrait;
class Repair extends SafeBaseCommand { use SubsCommandTrait; protected $group = 'AI-Ops'; protected $name='aiops:repair'; protected $description='Apply safe aiops repairs'; protected $options=['--json'=>'JSON','--dry-run'=>'Dry']; public function run(array $params){$this->parseParams($params);$json=$this->optBool('json');$dry=$this->optBool('dry-run');$actions=[];foreach(['aiops/runtime','chat/runtime'] as $d){if(!is_dir(ROOTPATH.$d)){if(!$dry){mkdir(ROOTPATH.$d,0775,true);} $actions[]="created {$d}";}} if(!is_file(ROOTPATH.'aiops/bridge-8500.js')){ if(!$dry){file_put_contents(ROOTPATH.'aiops/bridge-8500.js',"#!/usr/bin/env node\nconsole.log(JSON.stringify({ok:true,stub:true,ts:new Date().toISOString()}));\n");} $actions[]='created bridge-8500.js stub'; }
$report=['status'=>'ok','actions'=>$actions,'dry_run'=>$dry,'at'=>date('c')];$path=$this->writeDoc('repairs','aiops-repair-'.date('Y-m-d').'.md',"# AIOps Repair\n\n- ".implode("\n- ",$actions?:['No changes needed'])."\n");$report['report']=$path;$this->emit($report,$json);return EXIT_SUCCESS; }}
